<?php
/** Reversible integration checks for a local WordPress site with Etch active. */
wp_set_current_user(1);
function native_assert($ok,$label){if(!$ok)throw new Exception($label);echo 'PASS '.$label.PHP_EOL;}
function native_payload($args){return rtrim(strtr(base64_encode(wp_json_encode($args)),'+/','-_'),'=');}
$before=get_option('etch_loops',[]);$backup=get_option('lfe_native_query_backup_v1',false);
try{
 $nested=['posts_per_page'=>'$count ?? 3','meta_query'=>['relation'=>'OR','named'=>['key'=>'rating','value'=>2,'compare'=>'>'],['relation'=>'AND',['key'=>'color','value'=>['red','blue'],'compare'=>'IN'],['key'=>'missing','compare'=>'NOT EXISTS']]],'orderby'=>['date'=>'DESC','title'=>'ASC']];
 $cases=['wp-query'=>['post_type'=>'post']+$nested,'main-query'=>$nested,'wp-users'=>['number'=>'$count ?? 2','role__in'=>['editor','author']],'wp-terms'=>['taxonomy'=>['category','post_tag'],'number'=>'$count ?? 3','offset'=>1]];
 $fixtures=$before;
 foreach($cases as$type=>$args){$id='lfeNativeTest'.$type;if(isset($fixtures[$id]))throw new Exception('Temporary key exists');$carrier=$type==='wp-terms'?['taxonomy'=>'_looper_etch_v2:'.native_payload($args).'|$count ?? 3']:['meta_query'=>[['key'=>'_looper_etch_v2','value'=>native_payload($args),'compare'=>'='],['key'=>'_looper_etch_v2_param_0','value'=>'$count ?? 3','compare'=>'=']]];$fixtures[$id]=['key'=>'nativeTest'.str_replace('-','',$type),'name'=>'Native test','global'=>false,'future'=>['preserve'=>true],'config'=>['type'=>$type,'args'=>$carrier,'futureConfig'=>true]];native_assert(lfe_native_args($carrier,$type)===$args,'Decode v2 '.$type.' parameters and nested data');}
 $gallery=['post_type'=>'attachment','orderby'=>'ID','meta_query'=>['relation'=>'OR','rating'=>['key'=>'rating','value'=>2],['key'=>'_looper_etch_v1_post_parent','value'=>'$parent ?? 12'],['key'=>'_looper_etch_v1_post_mime_type','value'=>'image'],['key'=>'_looper_etch_v1_orderby','value'=>'collection_order']]];
 $fixtures['lfeNativeTestGallery']=['key'=>'nativeTestGallery','name'=>'Gallery','global'=>true,'config'=>['type'=>'wp-query','args'=>$gallery]];
 $fixtures['lfeNativeTestCorrupt']=['key'=>'nativeTestCorrupt','name'=>'Corrupt','config'=>['type'=>'wp-query','args'=>['meta_query'=>[['key'=>'_looper_etch_v2','value'=>'broken']]]]];
 update_option('etch_loops',$fixtures);$result=lfe_migrate_native_queries();native_assert(!is_wp_error($result)&&count($result['converted'])>=5&&count($result['errors'])===1,'Migrate valid definitions and report corrupt payload');$after=get_option('etch_loops');
 foreach($fixtures as$id=>$loop){if(!str_starts_with($id,'lfeNativeTest')||$id==='lfeNativeTestCorrupt')continue;$expected=$loop;$expected['config']['args']=lfe_native_args($loop['config']['args'],$loop['config']['type']);native_assert($after[$id]===$expected,'Retain ID, key, scope and unknown properties: '.$id);}
 native_assert($after['lfeNativeTestCorrupt']===$fixtures['lfeNativeTestCorrupt'],'Corrupt definition untouched');$args=$after['lfeNativeTestGallery']['config']['args'];native_assert($args['post_parent']==='$parent ?? 12'&&$args['post_mime_type']==='image'&&$args['orderby']==='collection_order'&&array_keys($args['meta_query'])===['relation','rating'],'v1 gallery preserves real named metadata and OR relation');
 native_assert(!lfe_migrate_native_queries()['converted'],'Migration is idempotent');native_assert(get_option('lfe_native_query_backup_v1',false)!==false,'Migration backup exists');native_assert(!isset(wp_load_alloptions()['lfe_native_query_backup_v1']),'Backup is not autoloaded');
 $id='lfeNativeTestwp-query';$original=$after[$id];$definition=$original;$definition['config']['args']['posts_per_page']='$count ?? 5';unset($definition['future'],$definition['config']['futureConfig']);$request=new WP_REST_Request('POST','/looper-for-etch/v1/native-query');$request->set_header('Content-Type','application/json');$request->set_body(wp_json_encode(['id'=>$id,'definition'=>$definition,'expected'=>$original]));$saved=rest_do_request($request);native_assert($saved->get_status()===200,'Authenticated native endpoint saves edited query');$actual=get_option('etch_loops')[$id];native_assert($actual['config']['args']['posts_per_page']==='$count ?? 5'&&$actual['future']===$original['future']&&$actual['config']['futureConfig'],'Update preserves unknown fields');native_assert(rest_do_request($request)->get_status()===409,'Reject stale query edit');$reordered=$actual;$meta=$reordered['config']['args']['meta_query'];$relation=$meta['relation'];unset($meta['relation']);$meta['relation']=$relation;$reordered['config']['args']['meta_query']=$meta;native_assert(lfe_native_equal($actual,$reordered),'JSON group key reordering does not cause false conflict');native_assert(is_wp_error(lfe_write_native_registry($after,$fixtures)),'Atomic write rejects stale registry');
 wp_set_current_user(0);native_assert(rest_do_request($request)->get_status()===401,'Deny anonymous save');native_assert(!has_filter('option_etch_loops','lfe_expand_saved_queries'),'No runtime decoder');
}finally{wp_set_current_user(1);update_option('etch_loops',$before);if($backup===false)delete_option('lfe_native_query_backup_v1');else update_option('lfe_native_query_backup_v1',$backup,false);}
